import {
  BasePipelineSolver,
  definePipelineStep,
  type PipelineStep,
} from "@tscircuit/solver-utils"
import type { SimpleRouteJson } from "./types/srj-types"
import type { GridFill3DOptions, XYRect } from "./rectdiff-types"
import type { CapacityMeshNode } from "./types/capacity-mesh-types"
import type { GraphicsObject } from "graphics-debug"
import { GapFillSolverPipeline } from "./solvers/GapFillSolver/GapFillSolverPipeline"
import { OuterLayerContainmentMergeSolver } from "./solvers/OuterLayerContainmentMergeSolver/OuterLayerContainmentMergeSolver"
import { RectDiffGridSolverPipeline } from "./solvers/RectDiffGridSolverPipeline/RectDiffGridSolverPipeline"
import { createBaseVisualization } from "./rectdiff-visualization"
import { buildFinalRectDiffVisualization } from "./buildFinalRectDiffVisualization"
import { computeInverseRects } from "./solvers/RectDiffSeedingSolver/computeInverseRects"
import { buildZIndexMap } from "./solvers/RectDiffSeedingSolver/layers"
import { buildObstacleClearanceGraphics } from "./utils/renderObstacleClearance"
import { mergeGraphics } from "graphics-debug"

export interface RectDiffPipelineInput {
  simpleRouteJson: SimpleRouteJson
  gridOptions?: Partial<GridFill3DOptions>
  obstacleClearance?: number
  /**
   * Maximum number of gap-fill expansion passes to run after the initial
   * rect-diff grid is built. Set to 1 for the original single-pass behavior;
   * higher values let nodes created by a pass expand again in later passes.
   */
  maxGapFillPasses: number
}

export class RectDiffPipeline extends BasePipelineSolver<RectDiffPipelineInput> {
  rectDiffGridSolverPipeline?: RectDiffGridSolverPipeline
  gapFillSolver?: GapFillSolverPipeline
  outerLayerContainmentMergeSolver?: OuterLayerContainmentMergeSolver
  boardVoidRects: XYRect[] | undefined
  zIndexByName?: Map<string, number>
  layerNames?: string[]

  override pipelineDef: PipelineStep<any>[] = [
    definePipelineStep(
      "rectDiffGridSolverPipeline",
      RectDiffGridSolverPipeline,
      (rectDiffPipeline: RectDiffPipeline) => [
        {
          bounds: rectDiffPipeline.inputProblem.simpleRouteJson.bounds,
          obstacles: rectDiffPipeline.inputProblem.simpleRouteJson.obstacles,
          connections:
            rectDiffPipeline.inputProblem.simpleRouteJson.connections,
          outline: rectDiffPipeline.inputProblem.simpleRouteJson.outline
            ? { outline: rectDiffPipeline.inputProblem.simpleRouteJson.outline }
            : undefined,
          layerCount: rectDiffPipeline.inputProblem.simpleRouteJson.layerCount,
          gridOptions: rectDiffPipeline.inputProblem.gridOptions,
          boardVoidRects: rectDiffPipeline.boardVoidRects,
          layerNames: rectDiffPipeline.layerNames,
          zIndexByName: rectDiffPipeline.zIndexByName,
          minTraceWidth:
            rectDiffPipeline.inputProblem.simpleRouteJson.minTraceWidth,
          obstacleClearance: rectDiffPipeline.inputProblem.obstacleClearance,
        },
      ],
    ),
    definePipelineStep(
      "gapFillSolver",
      GapFillSolverPipeline,
      (rectDiffPipeline: RectDiffPipeline) => [
        {
          meshNodes:
            rectDiffPipeline.rectDiffGridSolverPipeline?.getOutput()
              .meshNodes ?? [],
          boardVoid: {
            boardVoidRects: rectDiffPipeline.boardVoidRects || [],
            layerCount:
              rectDiffPipeline.inputProblem.simpleRouteJson.layerCount || 0,
          },
          maxGapFillPasses: rectDiffPipeline.inputProblem.maxGapFillPasses,
        },
      ],
    ),
    definePipelineStep(
      "outerLayerContainmentMergeSolver",
      OuterLayerContainmentMergeSolver,
      (rectDiffPipeline: RectDiffPipeline) => [
        {
          meshNodes:
            rectDiffPipeline.gapFillSolver?.getOutput().outputNodes ??
            rectDiffPipeline.rectDiffGridSolverPipeline?.getOutput()
              .meshNodes ??
            [],
          simpleRouteJson: rectDiffPipeline.inputProblem.simpleRouteJson,
          zIndexByName: rectDiffPipeline.zIndexByName ?? new Map(),
          obstacleClearance: rectDiffPipeline.inputProblem.obstacleClearance,
        },
      ],
    ),
  ]

  override _setup(): void {
    const { zIndexByName, layerNames } = buildZIndexMap({
      obstacles: this.inputProblem.simpleRouteJson.obstacles,
      layerCount: this.inputProblem.simpleRouteJson.layerCount,
    })
    this.zIndexByName = zIndexByName
    this.layerNames = layerNames
    if (this.inputProblem.simpleRouteJson.outline) {
      this.boardVoidRects = computeInverseRects(
        {
          x: this.inputProblem.simpleRouteJson.bounds.minX,
          y: this.inputProblem.simpleRouteJson.bounds.minY,
          width:
            this.inputProblem.simpleRouteJson.bounds.maxX -
            this.inputProblem.simpleRouteJson.bounds.minX,
          height:
            this.inputProblem.simpleRouteJson.bounds.maxY -
            this.inputProblem.simpleRouteJson.bounds.minY,
        },
        this.inputProblem.simpleRouteJson.outline ?? [],
      )
    }
  }

  override getConstructorParams() {
    return [this.inputProblem]
  }

  private throughHoleMeshNodesMemo?: CapacityMeshNode[]

  private getRawMeshNodes(): CapacityMeshNode[] {
    const outerLayerMergeOutput =
      this.outerLayerContainmentMergeSolver?.getOutput()
    if (outerLayerMergeOutput) {
      return outerLayerMergeOutput.outputNodes
    }
    const gapFillOutput = this.gapFillSolver?.getOutput()
    if (gapFillOutput) {
      return gapFillOutput.outputNodes
    }
    if (this.rectDiffGridSolverPipeline) {
      return this.rectDiffGridSolverPipeline.getOutput().meshNodes
    }
    return []
  }

  override getOutput(): { meshNodes: CapacityMeshNode[] } {
    const rawNodes = this.getRawMeshNodes()
    if (this.inputProblem.simpleRouteJson.viaMode !== "through-hole") {
      return { meshNodes: rawNodes }
    }
    // THROUGH-HOLE via mode: a via drilled top↔bottom is conductive on every layer, so it may
    // only be born where the FULL board column is clear. A node's availableZ already encodes
    // which layers are free at its footprint (obstacles carve it), so a node is via-capable iff
    // availableZ spans the whole stack. Any node with only *some* layers free would let the
    // router drop a via there (a blind/buried via, or one that drills the pad on a missing
    // layer) — split it into one single-layer node per free layer. Traces still route on each
    // layer, but no via can be born (a single-z node offers no other z to hop to). This is the
    // one place every downstream solver variant agrees on: they all read availableZ.
    if (!this.throughHoleMeshNodesMemo) {
      this.throughHoleMeshNodesMemo = splitNonViaCapableNodes(
        rawNodes,
        this.inputProblem.simpleRouteJson.layerCount,
      )
    }
    return { meshNodes: this.throughHoleMeshNodesMemo }
  }

  override initialVisualize(): GraphicsObject {
    const base = createBaseVisualization(
      this.inputProblem.simpleRouteJson,
      "RectDiffPipeline - Initial",
    )
    const clearance = buildObstacleClearanceGraphics({
      srj: this.inputProblem.simpleRouteJson,
      clearance: this.inputProblem.obstacleClearance,
    })

    // Show initial mesh nodes from grid pipeline if available
    const initialNodes =
      this.rectDiffGridSolverPipeline?.getOutput().meshNodes ?? []

    const nodeRects: GraphicsObject = {
      title: "Initial Nodes",
      coordinateSystem: "cartesian",
      rects: initialNodes.map((node) => ({
        center: node.center,
        width: node.width,
        height: node.height,
        stroke: "rgba(0, 0, 0, 0.3)",
        fill: "rgba(100, 100, 100, 0.1)",
        layer: `z${node.availableZ.join(",")}`,
        label: [
          `node ${node.capacityMeshNodeId}`,
          `z:${node.availableZ.join(",")}`,
        ].join("\n"),
      })),
    }

    return mergeGraphics(mergeGraphics(base, clearance), nodeRects)
  }

  override finalVisualize(): GraphicsObject {
    return buildFinalRectDiffVisualization({
      srj: this.inputProblem.simpleRouteJson,
      meshNodes: this.getOutput().meshNodes,
      obstacleClearance: this.inputProblem.obstacleClearance,
    })
  }
}

/**
 * THROUGH-HOLE via mode helper. A node is via-capable only where the entire board column is
 * clear (availableZ spans all layers). A node with a strict subset of layers free has an
 * obstacle on the missing layer(s), so a via born there would be blind/buried or drill that
 * obstacle — split it into one single-layer node per free layer. Single-layer and full-stack
 * nodes pass through unchanged.
 */
function splitNonViaCapableNodes(
  nodes: CapacityMeshNode[],
  layerCount: number,
): CapacityMeshNode[] {
  const out: CapacityMeshNode[] = []
  for (const node of nodes) {
    const z = node.availableZ
    if (z.length <= 1 || z.length >= layerCount) {
      out.push(node)
      continue
    }
    for (const singleZ of z) {
      out.push({
        ...node,
        capacityMeshNodeId: `${node.capacityMeshNodeId}_thz${singleZ}`,
        availableZ: [singleZ],
      })
    }
  }
  return out
}
